/**
 * RQdinn Client OS — relational schema.
 *
 * Conventions
 * - Primary keys are UUIDs generated by Postgres.
 * - Monetary amounts are stored as integers in minor units (paise for INR).
 * - Column names are snake_case in the database (drizzle `casing: "snake_case"`).
 */
import { relations, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  boolean,
  date,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const id = () => uuid().primaryKey().default(sql`gen_random_uuid()`);
const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/* ───────────────────────────── Enums ───────────────────────────── */

export const userRole = pgEnum("user_role", ["admin", "team", "client"]);
export const clientStatus = pgEnum("client_status", ["lead", "active", "on_hold", "completed", "maintenance"]);
export const projectPhase = pgEnum("project_phase", ["active", "live", "maintenance", "on_hold", "cancelled"]);
export const stepStatus = pgEnum("step_status", ["not_started", "in_progress", "waiting", "completed"]);
export const pipelineStage = pgEnum("pipeline_stage", [
  "new",
  "onboarding",
  "development",
  "review",
  "payment_pending",
  "ready_to_launch",
  "live",
]);
export const onboardingStatus = pgEnum("onboarding_status", ["not_started", "in_progress", "completed"]);
export const answerStatus = pgEnum("answer_status", ["answered", "client_later", "not_applicable"]);
export const documentType = pgEnum("document_type", ["agreement", "invoice", "receipt", "proposal", "brief", "other"]);
export const invoiceStatus = pgEnum("invoice_status", ["draft", "sent", "partially_paid", "paid", "void"]);
export const milestoneKind = pgEnum("milestone_kind", ["advance", "final", "annual", "other"]);
export const milestoneStatus = pgEnum("milestone_status", ["pending", "paid"]);
export const paymentMethod = pgEnum("payment_method", ["bank_transfer", "upi", "cash", "card", "cheque", "gateway", "other"]);
export const agreementStatus = pgEnum("agreement_status", ["draft", "sent", "accepted"]);
export const taskStatus = pgEnum("task_status", ["todo", "in_progress", "waiting", "completed"]);
export const taskPriority = pgEnum("task_priority", ["low", "medium", "high", "urgent"]);
export const previewStatus = pgEnum("preview_status", ["draft", "in_review", "changes_requested", "approved", "superseded"]);
export const revisionStatus = pgEnum("revision_status", ["pending", "in_progress", "completed"]);
export const maintenanceStatus = pgEnum("maintenance_status", ["new", "in_progress", "waiting_client", "completed"]);
export const maintenanceType = pgEnum("maintenance_type", [
  "text",
  "image",
  "menu",
  "contact",
  "section",
  "bug",
  "other",
]);
export const serviceBilling = pgEnum("service_billing", ["one_time", "monthly", "yearly"]);

/* ───────────────────────────── Identity ───────────────────────────── */

export const users = pgTable(
  "users",
  {
    id: id(),
    name: text().notNull(),
    email: text().notNull(),
    passwordHash: text().notNull(),
    role: userRole().notNull().default("team"),
    title: text(),
    phone: text(),
    /** Set for client users: the company they belong to. */
    clientId: uuid().references((): AnyPgColumn => clients.id, { onDelete: "cascade" }),
    isActive: boolean().notNull().default(true),
    lastLoginAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("users_email_idx").on(sql`lower(${t.email})`)],
);

export const sessions = pgTable(
  "sessions",
  {
    id: id(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    /** SHA-256 of the opaque token stored in the cookie. */
    tokenHash: text().notNull(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    userAgent: text(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("sessions_token_idx").on(t.tokenHash)],
);

/* ───────────────────────────── Clients ───────────────────────────── */

export const clients = pgTable(
  "clients",
  {
    id: id(),
    companyName: text().notNull(),
    industry: text().notNull().default("other"),
    status: clientStatus().notNull().default("lead"),
    address: text(),
    city: text(),
    website: text(),
    googleBusinessUrl: text(),
    instagram: text(),
    notes: text(),
    assignedToId: uuid().references((): AnyPgColumn => users.id, { onDelete: "set null" }),
    isDemo: boolean().notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("clients_status_idx").on(t.status)],
);

export const clientContacts = pgTable(
  "client_contacts",
  {
    id: id(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    name: text().notNull(),
    role: text(),
    phone: text(),
    email: text(),
    whatsapp: text(),
    isPrimary: boolean().notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index("client_contacts_client_idx").on(t.clientId)],
);

/* ───────────────────────────── Workflows ───────────────────────────── */

export const workflows = pgTable("workflows", {
  id: id(),
  name: text().notNull(),
  slug: text().notNull().unique(),
  description: text(),
  serviceType: text().notNull().default("website"),
  isArchived: boolean().notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const workflowSteps = pgTable(
  "workflow_steps",
  {
    id: id(),
    workflowId: uuid()
      .notNull()
      .references(() => workflows.id, { onDelete: "cascade" }),
    position: integer().notNull(),
    name: text().notNull(),
    /**
     * Semantic key the workflow engine reacts to (agreement, advance_payment,
     * onboarding, content_collection, development, client_review, final_approval,
     * final_payment, domain_hosting, deployment, maintenance …). Custom steps use "custom".
     */
    key: text().notNull().default("custom"),
    pipelineStage: pipelineStage().notNull().default("new"),
    description: text(),
    clientVisible: boolean().notNull().default(true),
    clientLabel: text(),
  },
  (t) => [index("workflow_steps_workflow_idx").on(t.workflowId, t.position)],
);

/* ───────────────────────────── Projects ───────────────────────────── */

export const projects = pgTable(
  "projects",
  {
    id: id(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    workflowId: uuid().references(() => workflows.id, { onDelete: "set null" }),
    name: text().notNull(),
    serviceType: text().notNull().default("website"),
    description: text(),
    value: integer().notNull().default(0),
    annualValue: integer().notNull().default(0),
    currency: text().notNull().default("INR"),
    phase: projectPhase().notNull().default("active"),
    currentStepId: uuid(),
    progress: integer().notNull().default(0),
    assignedToId: uuid().references(() => users.id, { onDelete: "set null" }),
    startDate: date(),
    dueDate: date(),
    // Onboarding call scheduling (Google Calendar-ready)
    onboardingAt: timestamp({ withTimezone: true }),
    onboardingMeetingLink: text(),
    onboardingAssigneeId: uuid().references(() => users.id, { onDelete: "set null" }),
    calendarEventId: text(),
    liveUrl: text(),
    isDemo: boolean().notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("projects_client_idx").on(t.clientId), index("projects_assigned_idx").on(t.assignedToId)],
);

export const projectSteps = pgTable(
  "project_steps",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    workflowStepId: uuid().references(() => workflowSteps.id, { onDelete: "set null" }),
    position: integer().notNull(),
    name: text().notNull(),
    key: text().notNull().default("custom"),
    pipelineStage: pipelineStage().notNull().default("new"),
    clientVisible: boolean().notNull().default(true),
    clientLabel: text(),
    status: stepStatus().notNull().default("not_started"),
    assignedToId: uuid().references(() => users.id, { onDelete: "set null" }),
    notes: text(),
    dueDate: date(),
    startedAt: timestamp({ withTimezone: true }),
    completedAt: timestamp({ withTimezone: true }),
    updatedAt: updatedAt(),
  },
  (t) => [index("project_steps_project_idx").on(t.projectId, t.position)],
);

/* ───────────────────────────── Onboarding ───────────────────────────── */

export const onboardingForms = pgTable("onboarding_forms", {
  id: id(),
  projectId: uuid()
    .notNull()
    .unique()
    .references(() => projects.id, { onDelete: "cascade" }),
  status: onboardingStatus().notNull().default("not_started"),
  currentSection: text().notNull().default("business"),
  progress: integer().notNull().default(0),
  callNotes: text(),
  startedAt: timestamp({ withTimezone: true }),
  completedAt: timestamp({ withTimezone: true }),
  completedById: uuid().references(() => users.id, { onDelete: "set null" }),
  updatedAt: updatedAt(),
});

export const onboardingAnswers = pgTable(
  "onboarding_answers",
  {
    id: id(),
    formId: uuid()
      .notNull()
      .references(() => onboardingForms.id, { onDelete: "cascade" }),
    section: text().notNull(),
    fieldKey: text().notNull(),
    value: jsonb(),
    status: answerStatus().notNull().default("answered"),
    updatedById: uuid().references(() => users.id, { onDelete: "set null" }),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("onboarding_answers_field_idx").on(t.formId, t.fieldKey)],
);

/* ───────────────────────────── Files & documents ───────────────────────────── */

export const files = pgTable(
  "files",
  {
    id: id(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    projectId: uuid().references(() => projects.id, { onDelete: "cascade" }),
    folder: text().notNull().default("Other"),
    name: text().notNull(),
    storageKey: text().notNull(),
    mimeType: text().notNull(),
    size: integer().notNull(),
    uploadedById: uuid().references(() => users.id, { onDelete: "set null" }),
    /** Onboarding field this file answers (e.g. "brand.logo"). */
    onboardingFieldKey: text(),
    revisionId: uuid(),
    maintenanceRequestId: uuid(),
    createdAt: createdAt(),
  },
  (t) => [index("files_client_idx").on(t.clientId), index("files_project_idx").on(t.projectId)],
);

/** Free-form documents (proposals, briefs, receipts, uploaded contracts…). Agreements and invoices have their own tables. */
export const documents = pgTable(
  "documents",
  {
    id: id(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    projectId: uuid().references(() => projects.id, { onDelete: "cascade" }),
    type: documentType().notNull().default("other"),
    name: text().notNull(),
    status: text().notNull().default("final"),
    fileId: uuid().references(() => files.id, { onDelete: "set null" }),
    clientVisible: boolean().notNull().default(true),
    createdById: uuid().references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("documents_client_idx").on(t.clientId)],
);

/* ───────────────────────────── Agreements ───────────────────────────── */

export const agreementTemplates = pgTable("agreement_templates", {
  id: id(),
  name: text().notNull(),
  body: text().notNull(),
  isDefault: boolean().notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const agreements = pgTable(
  "agreements",
  {
    id: id(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    templateId: uuid().references(() => agreementTemplates.id, { onDelete: "set null" }),
    title: text().notNull(),
    body: text().notNull(),
    variables: jsonb().$type<Record<string, string>>().notNull().default({}),
    status: agreementStatus().notNull().default("draft"),
    sentAt: timestamp({ withTimezone: true }),
    acceptedAt: timestamp({ withTimezone: true }),
    acceptedById: uuid().references(() => users.id, { onDelete: "set null" }),
    acceptedName: text(),
    acceptedIp: text(),
    // E-signature integration points
    signatureProvider: text(),
    signatureEnvelopeId: text(),
    createdById: uuid().references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("agreements_project_idx").on(t.projectId)],
);

/* ───────────────────────────── Billing ───────────────────────────── */

export const invoices = pgTable(
  "invoices",
  {
    id: id(),
    number: text().notNull().unique(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    projectId: uuid().references(() => projects.id, { onDelete: "set null" }),
    status: invoiceStatus().notNull().default("draft"),
    issueDate: date().notNull(),
    dueDate: date(),
    notes: text(),
    subtotal: integer().notNull().default(0),
    total: integer().notNull().default(0),
    sentAt: timestamp({ withTimezone: true }),
    paidAt: timestamp({ withTimezone: true }),
    createdById: uuid().references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("invoices_client_idx").on(t.clientId)],
);

export const invoiceItems = pgTable("invoice_items", {
  id: id(),
  invoiceId: uuid()
    .notNull()
    .references(() => invoices.id, { onDelete: "cascade" }),
  position: integer().notNull().default(0),
  description: text().notNull(),
  quantity: integer().notNull().default(1),
  unitPrice: integer().notNull(),
  amount: integer().notNull(),
});

/** Planned payment schedule for a project (advance / final / annual …). */
export const paymentMilestones = pgTable(
  "payment_milestones",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    position: integer().notNull().default(0),
    label: text().notNull(),
    kind: milestoneKind().notNull().default("other"),
    amount: integer().notNull(),
    dueDate: date(),
    status: milestoneStatus().notNull().default("pending"),
    invoiceId: uuid().references(() => invoices.id, { onDelete: "set null" }),
    paidAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("payment_milestones_project_idx").on(t.projectId)],
);

/** Money actually received. Recorded by staff or (later) by a payment-provider webhook. */
export const payments = pgTable(
  "payments",
  {
    id: id(),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    projectId: uuid().references(() => projects.id, { onDelete: "set null" }),
    milestoneId: uuid().references(() => paymentMilestones.id, { onDelete: "set null" }),
    invoiceId: uuid().references(() => invoices.id, { onDelete: "set null" }),
    amount: integer().notNull(),
    method: paymentMethod().notNull().default("bank_transfer"),
    reference: text(),
    notes: text(),
    receivedAt: timestamp({ withTimezone: true }).notNull(),
    provider: text().notNull().default("manual"),
    providerPaymentId: text(),
    recordedById: uuid().references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("payments_project_idx").on(t.projectId)],
);

/* ───────────────────────────── Delivery ───────────────────────────── */

export const tasks = pgTable(
  "tasks",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    projectStepId: uuid().references(() => projectSteps.id, { onDelete: "set null" }),
    title: text().notNull(),
    description: text(),
    assigneeId: uuid().references(() => users.id, { onDelete: "set null" }),
    priority: taskPriority().notNull().default("medium"),
    status: taskStatus().notNull().default("todo"),
    dueDate: date(),
    position: integer().notNull().default(0),
    completedAt: timestamp({ withTimezone: true }),
    createdById: uuid().references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("tasks_project_idx").on(t.projectId), index("tasks_assignee_idx").on(t.assigneeId)],
);

/** A reviewable build shared with the client (V1, V2 …). */
export const previews = pgTable(
  "previews",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    version: text().notNull(),
    url: text().notNull(),
    notes: text(),
    status: previewStatus().notNull().default("draft"),
    sentAt: timestamp({ withTimezone: true }),
    createdById: uuid().references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("previews_project_idx").on(t.projectId)],
);

export const revisions = pgTable(
  "revisions",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    previewId: uuid().references(() => previews.id, { onDelete: "set null" }),
    round: integer().notNull(),
    status: revisionStatus().notNull().default("pending"),
    clientFeedback: text().notNull(),
    response: text(),
    requestedById: uuid().references(() => users.id, { onDelete: "set null" }),
    closedById: uuid().references(() => users.id, { onDelete: "set null" }),
    closedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("revisions_project_idx").on(t.projectId)],
);

export const approvals = pgTable("approvals", {
  id: id(),
  projectId: uuid()
    .notNull()
    .references(() => projects.id, { onDelete: "cascade" }),
  previewId: uuid().references(() => previews.id, { onDelete: "set null" }),
  version: text().notNull(),
  approvedById: uuid().references(() => users.id, { onDelete: "set null" }),
  approvedName: text().notNull(),
  confirmation: text().notNull(),
  ipAddress: text(),
  userAgent: text(),
  approvedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

export const deploymentItems = pgTable(
  "deployment_items",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    position: integer().notNull().default(0),
    key: text().notNull(),
    label: text().notNull(),
    required: boolean().notNull().default(true),
    isDone: boolean().notNull().default(false),
    doneAt: timestamp({ withTimezone: true }),
    doneById: uuid().references(() => users.id, { onDelete: "set null" }),
  },
  (t) => [uniqueIndex("deployment_items_key_idx").on(t.projectId, t.key)],
);

export const launches = pgTable("launches", {
  id: id(),
  projectId: uuid()
    .notNull()
    .unique()
    .references(() => projects.id, { onDelete: "cascade" }),
  url: text().notNull(),
  launchedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  hostingRenewalDate: date(),
  maintenanceRenewalDate: date(),
  analyticsUrl: text(),
  notes: text(),
  launchedById: uuid().references(() => users.id, { onDelete: "set null" }),
});

export const maintenanceRequests = pgTable(
  "maintenance_requests",
  {
    id: id(),
    projectId: uuid()
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    clientId: uuid()
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    type: maintenanceType().notNull().default("other"),
    title: text().notNull(),
    description: text().notNull(),
    status: maintenanceStatus().notNull().default("new"),
    priority: taskPriority().notNull().default("medium"),
    response: text(),
    requestedById: uuid().references(() => users.id, { onDelete: "set null" }),
    assignedToId: uuid().references(() => users.id, { onDelete: "set null" }),
    resolvedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("maintenance_project_idx").on(t.projectId)],
);

/* ───────────────────────────── Signals ───────────────────────────── */

export const notifications = pgTable(
  "notifications",
  {
    id: id(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    event: text().notNull(),
    title: text().notNull(),
    body: text(),
    href: text(),
    readAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("notifications_user_idx").on(t.userId, t.createdAt)],
);

export const activityLogs = pgTable(
  "activity_logs",
  {
    id: id(),
    clientId: uuid().references((): AnyPgColumn => clients.id, { onDelete: "cascade" }),
    projectId: uuid().references(() => projects.id, { onDelete: "cascade" }),
    actorId: uuid().references(() => users.id, { onDelete: "set null" }),
    event: text().notNull(),
    description: text().notNull(),
    metadata: jsonb().$type<Record<string, unknown>>(),
    clientVisible: boolean().notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index("activity_client_idx").on(t.clientId, t.createdAt), index("activity_project_idx").on(t.projectId, t.createdAt)],
);

export const settings = pgTable("settings", {
  key: text().primaryKey(),
  value: jsonb().notNull(),
  updatedAt: updatedAt(),
});

/* ───────────────────────────── Sales ───────────────────────────── */

/** Service catalog used by the Services page price calculator. */
export const services = pgTable("services", {
  id: id(),
  name: text().notNull(),
  category: text().notNull().default("General"),
  description: text(),
  /** Paise. */
  price: integer().notNull(),
  billing: serviceBilling().notNull().default("one_time"),
  features: jsonb().$type<string[]>().notNull().default(sql`'[]'::jsonb`),
  position: integer().notNull().default(0),
  /** Hidden services stay in the catalog but can't be added to a quote. */
  isActive: boolean().notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** Showcase of delivered work, each linking to the live site. */
export const portfolioItems = pgTable("portfolio_items", {
  id: id(),
  title: text().notNull(),
  url: text().notNull(),
  clientName: text(),
  category: text(),
  description: text(),
  /** Optional cover image link; without it the page shows a live screenshot of the site. */
  imageUrl: text(),
  tags: jsonb().$type<string[]>().notNull().default(sql`'[]'::jsonb`),
  year: integer(),
  isFeatured: boolean().notNull().default(false),
  projectId: uuid().references(() => projects.id, { onDelete: "set null" }),
  createdById: uuid().references(() => users.id, { onDelete: "set null" }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/* ───────────────────────────── Relations ───────────────────────────── */

export const usersRelations = relations(users, ({ one }) => ({
  client: one(clients, { fields: [users.clientId], references: [clients.id] }),
}));

export const clientsRelations = relations(clients, ({ many, one }) => ({
  contacts: many(clientContacts),
  projects: many(projects),
  assignedTo: one(users, { fields: [clients.assignedToId], references: [users.id] }),
}));

export const clientContactsRelations = relations(clientContacts, ({ one }) => ({
  client: one(clients, { fields: [clientContacts.clientId], references: [clients.id] }),
}));

export const workflowsRelations = relations(workflows, ({ many }) => ({
  steps: many(workflowSteps),
}));

export const workflowStepsRelations = relations(workflowSteps, ({ one }) => ({
  workflow: one(workflows, { fields: [workflowSteps.workflowId], references: [workflows.id] }),
}));

export const projectsRelations = relations(projects, ({ one, many }) => ({
  client: one(clients, { fields: [projects.clientId], references: [clients.id] }),
  workflow: one(workflows, { fields: [projects.workflowId], references: [workflows.id] }),
  assignedTo: one(users, { fields: [projects.assignedToId], references: [users.id] }),
  steps: many(projectSteps),
  tasks: many(tasks),
  milestones: many(paymentMilestones),
  onboarding: one(onboardingForms),
  launch: one(launches),
}));

export const projectStepsRelations = relations(projectSteps, ({ one }) => ({
  project: one(projects, { fields: [projectSteps.projectId], references: [projects.id] }),
  assignedTo: one(users, { fields: [projectSteps.assignedToId], references: [users.id] }),
}));

export const onboardingFormsRelations = relations(onboardingForms, ({ one, many }) => ({
  project: one(projects, { fields: [onboardingForms.projectId], references: [projects.id] }),
  answers: many(onboardingAnswers),
}));

export const onboardingAnswersRelations = relations(onboardingAnswers, ({ one }) => ({
  form: one(onboardingForms, { fields: [onboardingAnswers.formId], references: [onboardingForms.id] }),
}));

export const invoicesRelations = relations(invoices, ({ one, many }) => ({
  client: one(clients, { fields: [invoices.clientId], references: [clients.id] }),
  project: one(projects, { fields: [invoices.projectId], references: [projects.id] }),
  items: many(invoiceItems),
}));

export const invoiceItemsRelations = relations(invoiceItems, ({ one }) => ({
  invoice: one(invoices, { fields: [invoiceItems.invoiceId], references: [invoices.id] }),
}));

export const paymentMilestonesRelations = relations(paymentMilestones, ({ one }) => ({
  project: one(projects, { fields: [paymentMilestones.projectId], references: [projects.id] }),
}));

export const tasksRelations = relations(tasks, ({ one }) => ({
  project: one(projects, { fields: [tasks.projectId], references: [projects.id] }),
  assignee: one(users, { fields: [tasks.assigneeId], references: [users.id] }),
}));

export const launchesRelations = relations(launches, ({ one }) => ({
  project: one(projects, { fields: [launches.projectId], references: [projects.id] }),
}));

